import { profileExamples, profileVocabulary } from './profile.js';

export const EXAMPLES_BASE = 'data/';

// FALLBACK ONLY. The demo corpus travels with the profile bundle: a deployment
// that names `examples` in its own data/profile.json decides what its example
// link loads. This list is what the app offers when the mounted bundle says
// nothing — the file names of the Dutch reference deployment, which is the
// bundle this repository is developed against. The e2e suite serves its own
// bundle and therefore its own list (test/e2e/data/demo/profile.json).
export const FALLBACK_DEMO_CORPUS = [
  'generiek/1-generiek-drietraps.ttl',
  'generiek/7-dekking-generiek.ttl',
  'generiek/archief-partof.ttl',
  'generiek/keten-offer-request-agreement.ttl',
  'vlierdam/vocabulaire.ttl',
  'vlierdam/velden.ttl',
  'vlierdam/beleid.ttl',
  'vlierdam/openftv.ttl',
];

export function demoCorpus() {
  const fromProfile = profileExamples();
  return fromProfile.length ? fromProfile : FALLBACK_DEMO_CORPUS;
}

export function vocabulary() {
  return profileVocabulary();
}

export function defaultExamples() {
  return [...demoCorpus(), ...vocabulary()];
}

export function exampleSearchString() {
  return '?' + demoCorpus().map((n) => `src=${encodeURIComponent(EXAMPLES_BASE + n)}`).join('&');
}

export function vocabularyName(url) {
  const u = String(url || '');
  return vocabulary().find((n) => u === EXAMPLES_BASE + n || u.endsWith('/' + n)) || null;
}
