import { createSignal } from 'solid-js';
import { createStore } from 'solid-js/store';
import { defaultLang, getLang, normalizeLang, setLang } from '../model/i18n.js';
import { t } from '../model-boundary.js';

export type State = 'doc' | 'sparql';
export type Lang = 'nl' | 'en';
export type Lifecycle = 'active' | 'terminated' | 'future';

export const LIFECYCLES: Lifecycle[] = ['active', 'terminated', 'future'];

export interface Filters {
  status: Lifecycle[] | null;
  offer: string;
}

export interface View {
  state: State;
  src: string[];
  ttl: string[];
  sparql: string | null;
  policyScope: string | null;
  setScope: string | null;
  groupBy: string[] | null;
  lang: Lang;
  langExplicit: boolean;
  editMode: boolean;
  excludeGraphs: string[];
  filters: Filters;
}

function empty(): View {
  return {
    state: 'doc',
    src: [], ttl: [], sparql: null,
    policyScope: null, setScope: null,
    groupBy: null,
    // The chrome language of the BUNDLE, not a hard-coded one: a deployment
    // that ships `language` decides what a reader sees before they choose.
    lang: defaultLang() as Lang,
    langExplicit: false,
    editMode: false,
    excludeGraphs: [],
    filters: { status: null, offer: '' },
  };
}

const [view, setViewStore] = createStore<View>(empty());
export { view };

export function text(key: string, vars?: Record<string, unknown>): string {
  void view.lang;
  return t(key, vars);
}

function statusFromUrl(raw: string | null): Lifecycle[] | null {
  if (!raw) return null;
  const want = raw.split(',').map((s) => s.trim())
    .filter((s): s is Lifecycle => (LIFECYCLES as string[]).includes(s));
  return want.length ? want : null;
}

export function readFromUrl(search: string): void {
  const p = new URLSearchParams(search);
  const lang = normalizeLang(p.get('lang')) as Lang;
  setLang(lang);
  setViewStore({
    ...empty(),
    state: 'doc',
    src: p.getAll('src'),
    ttl: p.getAll('ttl'),
    sparql: p.get('sparql') || null,
    policyScope: p.get('policy') || null,
    setScope: p.get('set') || null,
    groupBy: p.has('groupby')
      ? String(p.get('groupby') || '').split(',').map((s) => s.trim()).filter(Boolean)
      : null,
    lang,
    langExplicit: p.has('lang'),
    editMode: p.get('edit') === '1',
    excludeGraphs: p.getAll('exclude-graph'),
    filters: { status: statusFromUrl(p.get('status')), offer: p.get('offer') || '' },
  });
}

const URL_KEYS = ['src', 'ttl', 'sparql', 'policy', 'set', 'groupby',
  'edit', 'exclude-graph', 'status', 'offer', 'lang'] as const;

// TOTAL: the whole store is written out, so store and address bar cannot drift.
// Parameters this store does not own are left untouched.
export function toUrl(w: View, basis?: URLSearchParams): URLSearchParams {
  const u = new URLSearchParams(basis);
  for (const k of URL_KEYS) u.delete(k);
  for (const s of w.src) u.append('src', s);
  for (const s of w.ttl) u.append('ttl', s);
  if (w.sparql) u.set('sparql', w.sparql);
  if (w.policyScope) u.set('policy', w.policyScope);
  if (w.setScope) u.set('set', w.setScope);
  if (w.groupBy) u.set('groupby', w.groupBy.join(','));
  if (w.editMode) u.set('edit', '1');
  for (const g of w.excludeGraphs) u.append('exclude-graph', g);
  if (w.filters.status) {
    u.set('status', LIFECYCLES.filter((s) => w.filters.status!.includes(s)).join(','));
  }
  if (w.filters.offer) u.set('offer', w.filters.offer);
  if (w.langExplicit) u.set('lang', w.lang);
  return u;
}

function writeUrl(w: View): void {
  if (typeof history === 'undefined' || !history.replaceState) return;
  const q = toUrl(w, new URLSearchParams(location.search)).toString();
  history.replaceState(null, '', q ? '?' + q : location.pathname);
}

export function setView(patch: Partial<View>): void {
  const next: Partial<View> = { ...patch };

  if ('lang' in next && next.lang) {
    const lang = normalizeLang(next.lang) as Lang;
    setLang(lang);
    next.lang = lang;
    next.langExplicit = true;
  }
  if (next.policyScope) next.setScope = null;
  else if (next.setScope) next.policyScope = null;
  if (next.filters && next.filters.status
      && next.filters.status.length === LIFECYCLES.length) {
    next.filters = { ...next.filters, status: null };
  }

  setViewStore(next as View);
  writeUrl(view);
}

export const currentLang = getLang;

const [noticeState, setNoticeSignal] =
  createSignal<{ key: string; vars?: Record<string, unknown> } | null>(null);

export const notice = (): string | null => noticeState()?.key ?? null;
export const noticeVars = (): Record<string, unknown> | undefined => noticeState()?.vars;

export function setNotice(key: string | null, vars?: Record<string, unknown>): void {
  setNoticeSignal(key ? { key, vars } : null);
}

export type Revealer = (ref: string) => boolean;

const revealers = new Set<Revealer>();

export function registerRevealer(fn: Revealer): () => void {
  revealers.add(fn);
  return () => { revealers.delete(fn); };
}

export function reveal(ref: string): boolean {
  if (!ref) return false;
  for (const fn of [...revealers]) {
    try { if (fn(ref)) return true; } catch {  }
  }
  return false;
}

const tick = (): Promise<void> => new Promise((r) => { setTimeout(r, 0); });

function findRef(ref: string): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  const safe = ref.replace(/["\\]/g, '\\$&');
  return document.querySelector(`[data-ref="${safe}"]`)
    || document.querySelector(`[data-iri="${safe}"]`);
}

async function scrollTo(target: HTMLElement, smooth: boolean): Promise<void> {
  if (typeof target.scrollIntoView !== 'function') return;
  target.scrollIntoView({ behavior: smooth ? 'smooth' : 'auto', block: 'start' });
  for (let i = 0; i < 12; i += 1) {
    await new Promise((r) => { setTimeout(r, 40); });
    const top = target.getBoundingClientRect().top;
    const height = typeof window !== 'undefined' ? window.innerHeight : 0;
    if (top >= -4 && top < Math.max(height, 1)) return;
  }
  target.scrollIntoView({ behavior: 'auto', block: 'start' });
}

export async function jump(ref: string, options: { smooth?: boolean } = {}): Promise<boolean> {
  if (!ref) return false;
  for (const fn of [...revealers]) {
    try { if (fn(ref)) break; } catch {  }
  }
  await tick();
  const target = findRef(ref);
  if (!target) return false;
  for (let n: HTMLElement | null = target; n; n = n.parentElement) {
    if (n instanceof HTMLDetailsElement) n.open = true;
  }
  await scrollTo(target, !!options.smooth);
  if (target.classList) {
    target.classList.remove('ui-flash');
    void target.offsetWidth;
    target.classList.add('ui-flash');
    setTimeout(() => target.classList.remove('ui-flash'), 1800);
  }
  return true;
}
