export type LoadStatus = 'empty' | 'loading' | 'ready' | 'error';
export type Engine = 'worker' | 'main-thread';
export type ListPhase = 'first' | null;
export type ListError = 'endpoint' | 'fullIndex' | null;
export type { Source };
export type CorpusError = ErrorInfo;
export type CorpusModel = Model;

const [model, setModel] = createSignal<CorpusModel | null>(null);
const [loadStatus, setLoadStatus] = createSignal<LoadStatus>('empty');
const [errors, setErrors] = createSignal<CorpusError[]>([]);
const [sources, setSources] = createSignal<Source[]>([]);
const [quadCount, setQuadCount] = createSignal(0);
const [engine, setMotor] = createSignal<Engine | null>(null);
const [nav, setNav] = createSignal<Nav>(null);
const [scopedNav, setScopedNav] = createSignal<Nav>(null);
const [scopeNotFound, setScopeNotFound] = createSignal<'policy' | 'set' | null>(null);
const [graph, setGraph] = createSignal<Graph | null>(null);
const [graphVersion, setGraphVersion] = createSignal(0);
const [endpoint, setEndpoint] = createSignal<string | null>(null);
const [endpointIsSource, setEndpointIsSource] = createSignal(false);
const [listPhase, setListPhase] = createSignal<ListPhase>(null);
const [compatIndex, setCompatIndex] = createSignal(false);
const [listError, setListError] = createSignal<ListError>(null);
const [loadNotice, setLoadNotice] = createSignal<string>('load.sources');
const [coveredCount, setCoveredCount] = createSignal<number | null>(null);

export {
  sources, compatIndex, endpoint, endpointIsSource, errors, coveredCount, graph, graphVersion,
  loadNotice,
  loadStatus, listPhase, listError, model, engine, nav, quadCount, scopedNav,
  scopeNotFound,
};

let seqNumber = 0;

let graphReady: Promise<void> = Promise.resolve();
let lastSetScope: string | null = null;
let lastPolicyScope: string | null = null;
let lastExcludeGraphs: string[] = [];
let lastRawExclude: string[] | undefined;

let baseSources: Source[] = [];
let baseErrors: CorpusError[] = [];

const withBase = (source: Source[]): Source[] => (baseSources.length
  ? [...baseSources, ...source] : source);
const withBaseErrors = (extra: CorpusError[]): CorpusError[] => (baseErrors.length
  ? [...baseErrors, ...extra] : extra);

function noteEndpoint(ep: string | null): void {
  setEndpoint(ep);
  lastExcludeGraphs = excludeGraphsFor(ep, lastRawExclude);
}

interface ToLoad {
  name: string;
  url: string;
  detect?: boolean;
  quiet?: boolean;
}

// Deduplicated on URL, first wins: two equal ?src= values share one named graph,
// so they would share one local copy and show two edit sources at once.
export function sourcesToLoad(
  p: { src: string[]; ttl?: string[]; sparql?: string | null; scope?: string | null },
): ToLoad[] {
  const all: ToLoad[] = [
    ...p.src.map((url) => ({ name: url, url, detect: true })),
    ...(p.ttl || []).map((url) => ({ name: url, url })),
  ];
  const seen = new Set<string>();
  const list = all.filter((t) => !seen.has(t.url) && !!seen.add(t.url));
  if (!list.length) return [];
  const alreadyVocab = new Set(list.map((t) => vocabularyName(t.url)).filter(Boolean));
  return [
    ...list,
    ...vocabulary().filter((n: string) => !alreadyVocab.has(n))
      .map((name: string) => ({ name, url: EXAMPLES_BASE + name, quiet: true })),
  ];
}

interface Fetched { sources: Source[]; errors: CorpusError[]; endpoints: string[] }

async function fetchSources(list: ToLoad[]): Promise<Fetched> {
  const out: Source[] = [];
  const error: CorpusError[] = [];
  const eps: string[] = [];
  const resultaten = await Promise.all(list.map(async ({ name, url, detect, quiet }) => {
    if (detect) {
      const r = await detectSource(url);
      if (r.kind === 'sparql') return { endpoint: r.url };
      if (r.kind === 'data') {
        return { source: { name, url, content: r.content, format: r.format } };
      }
      return quiet ? {} : { error: { url, message: r.message } };
    }
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const content = await r.text();
      return { source: { name, url, content, format: detectFormat(url, content) as string } };
    } catch (e) {
      if (quiet) return {};
      return { error: { url, message: e instanceof Error ? e.message : String(e) } };
    }
  }));
  for (const r of resultaten) {
    if (r.source) out.push(r.source);
    else if (r.endpoint) eps.push(r.endpoint);
    else if (r.error) error.push(r.error);
  }
  return { sources: out, errors: error, endpoints: eps };
}

async function buildFixtureModel(source: Source[], options: { setScope: string | null; lang: string }):
Promise<{ outcome: ModelResult; engine: Engine }> {
  try {
    const store = createStore();
    let reportDone: () => void = () => {};
    graphReady = new Promise<void>((r) => { reportDone = r; });
    const outcome = await loadSourcesInWorker(source, {
      setScope: options.setScope,
      lang: options.lang,
      onStore: (lading) => {
        if (!lading) { reportDone(); return; }
        void hydrateInto(store, lading).then(() => {
          setGraph(() => store);
          setGraphVersion((v) => v + 1);
          reportDone();
        });
      },
    });
    return { outcome, engine: 'worker' };
  } catch {
    const outcome = loadSources(source);
    setGraph(() => outcome.store ?? null);
    setGraphVersion((v) => v + 1);
    graphReady = Promise.resolve();
    return { outcome, engine: 'main-thread' };
  }
}

function ownScoping(navTree: Nav, scope: Scope): Nav {
  if (!navTree) return null;
  if (scope.policy) return scopeNavToPolicy(navTree, scope.policy)?.nav ?? null;
  const g = graph();
  if (!scope.set || !g) return null;
  return scopeNavToSet(navTree, g, scope.set)?.nav ?? null;
}

interface Scope { set: string | null; policy: string | null }

const currentScope = (): Scope => ({ set: lastSetScope, policy: lastPolicyScope });

export async function rebuild(
  options: { lang?: string; setScope?: string | null; policyScope?: string | null } = {},
): Promise<void> {
  const seq = seqNumber;
  if (!model()) return;
  if (options.setScope !== undefined) lastSetScope = options.setScope;
  if (options.policyScope !== undefined) lastPolicyScope = options.policyScope;
  await graphReady;
  if (seq !== seqNumber) return;
  const g = graph();
  if (!g) return;
  const m = buildModel(g);
  const n = buildNav(m);
  const scope = currentScope();
  setModel(m);
  setNav(() => n);
  setScopedNav(() => ownScoping(n, scope));
}

interface BuildOptions { setScope: string | null; policyScope: string | null; lang: string }

const [lazyLoaded, setLazyLoaded] = createSignal<{ iri: string; ttl: string; ep: string }[]>([]);

function remixSideLoaded(): boolean {
  const g = graph();
  if (!g || !lazyLoaded().length) return false;
  for (const k of lazyLoaded()) addSource(g, k.ttl, 'ttl', graphForSource({ url: k.ep }, 0));
  setGraphVersion((v) => v + 1);
  return true;
}

async function processSources(
  seq: number, source: Source[], extraErrors: CorpusError[], options: BuildOptions,
): Promise<boolean> {
  const { outcome, engine: gebruikt } = await buildFixtureModel(source, options);
  if (seq !== seqNumber) return false;
  setSources(source);
  setModel(outcome.model || null);
  setNav(() => outcome.nav ?? null);
  const gescoped = (outcome.scopedNav !== undefined && !options.policyScope)
    ? outcome.scopedNav
    : ownScoping(outcome.nav ?? null,
      { set: options.setScope, policy: options.policyScope });
  setScopedNav(() => gescoped);
  const gevraagd = options.policyScope ? 'policy' : (options.setScope ? 'set' : null);
  setScopeNotFound(gevraagd && !gescoped ? gevraagd : null);
  setQuadCount(outcome.quadCount || 0);
  setMotor(gebruikt);
  setErrors([...extraErrors, ...(outcome.errors || [])]);
  setLoadStatus(outcome.model ? 'ready' : 'error');
  await graphReady;
  if (seq !== seqNumber) return !!outcome.model;
  if (remixSideLoaded()) rebuildFromGraph();
  return !!outcome.model;
}

function reportError(seq: number, error: CorpusError): void {
  if (seq !== seqNumber) return;
  setErrors(withBaseErrors([error]));
  setLoadStatus('error');
}

async function loadFiles(seq: number, urls: ToLoad[], options: BuildOptions): Promise<void> {
  const fetched = await fetchSources(urls);
  if (seq !== seqNumber) return;
  if (fetched.endpoints.length) noteEndpoint(fetched.endpoints[0]);
  const ownSources = fetched.sources.filter((b) => !vocabularyName(b.url));
  const ep = endpoint();
  if (!ownSources.length && ep) {
    setLoadNotice('load.queryEndpointAt');
    setEndpointIsSource(true);
    await loadFromEndpoint(seq, ep, options.policyScope, options);
    return;
  }
  if (!ownSources.length) {
    setSources([]); setModel(null); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setErrors(fetched.errors);
    setLoadStatus('error');
    return;
  }
  if (ep) setEndpointIsSource(true);
  const pre = await preprocessed(fetched.sources);
  baseSources = pre.list;
  baseErrors = pre.error ? [pre.error, ...fetched.errors] : fetched.errors;
  await processSources(seq, baseSources, baseErrors, options);
  if (seq !== seqNumber || !ep) return;
  await loadFromEndpoint(seq, ep, options.policyScope, options);
}

async function loadScopeSource(seq: number, scopeIri: string, options: BuildOptions): Promise<void> {
  try {
    const r = await fetch(scopeIri);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const content = await r.text();
    if (seq !== seqNumber) return;
    const pre = await preprocessed([{
      name: scopeIri, url: scopeIri, content, format: detectFormat(scopeIri, content),
    }]);
    await processSources(seq, pre.list, pre.error ? [pre.error] : [], options);
  } catch (e) {
    reportError(seq, {
      url: scopeIri,
      message: t('err.scopeFetch', {
        iri: scopeIri, msg: e instanceof Error ? e.message : String(e),
      }),
    });
  }
}

async function indexRows(ep: string): Promise<Binding[]> {
  try {
    return await sparqlSelect(ep, policyListQuery());
  } catch (e) {
    if (!isEndpointTimeout(e)) throw e;
    try {
      const rows = await decomposedIndexRows(ep);
      setCompatIndex(true);
      return rows;
    } catch { throw e; }
  }
}

async function loadPolicyList(seq: number, ep: string, options: BuildOptions): Promise<void> {
  let firstView = false;
  try {
    const rows = await sparqlSelect(ep, policyListFirstQuery());
    if (seq !== seqNumber) return;
    if (rows.length) {
      setListPhase('first');
      firstView = await processSources(seq, withBase([{
        // RESIDUE: hardcoded Dutch chrome. This name is rendered in the
        name: text('src.endpointFirstView', { ep, n: rows.length }),
        url: ep, content: listSkeletonTurtle(rows), format: 'ttl', fromSparql: true,
      }]), withBaseErrors([]), options);
      if (firstView) setLoadStatus('loading');
    }
  } catch {
    setListPhase(null);
  }
  if (seq !== seqNumber) return;

  try {
    const [rows, cRows] = await Promise.all([
      indexRows(ep),
      sparqlSelect(ep, containerListQuery()).catch(() => [] as Binding[]),
    ]);
    if (seq !== seqNumber) return;
    setListPhase(null);
    const ttl = listSkeletonTurtle(rows) + containerSkeletonTurtle(cRows);
    await processSources(seq, withBase([{
      name: text('src.endpointPolicyList', {
        ep,
        n: rows.length,
        more: cRows.length ? text('src.endpointVersionRows', { m: cRows.length }) : '',
      }),
      url: ep, content: ttl, format: 'ttl', fromSparql: true,
    }]), withBaseErrors([]), options);
    if (seq !== seqNumber) return;
    await fetchCardDetails(seq);
  } catch (e) {
    if (seq !== seqNumber) return;
    setListPhase(null);
    const msg = e instanceof Error ? e.message : String(e);
    setListError(firstView ? 'fullIndex' : 'endpoint');
    setErrors(withBaseErrors([{ url: ep, message: msg }]));
    setLoadStatus('error');
  }
}

const FORM_SHAPES_KEY = 'urn:odrlvis:formShapes';
const LABELS_KEY = 'urn:odrlvis:nodeLabels';

interface FormShape { targetClass: string }
const readShapesFn = readShapes as unknown as (g: Graph) => FormShape[];
const bundledShapes = builtinShapes as unknown as (ttl?: string[]) => FormShape[];
const coveredClassesOf = coveredClasses as unknown as (
  g: Graph, shapes: FormShape[]) => Set<string>;
const coveredNodesFrom = coveredNodes as unknown as (
  g: Graph, classes: Set<string>, options?: { skipGraphs?: string[] },
) => { iris: Set<string>; blanks: number };
const hasOwnName = hasOwnLabel;

function formShapesTtl(ep: string): Promise<string> {
  return sparqlConstruct(ep, formShapesQuery({ excludeGraphs: lastExcludeGraphs }))
    .catch(() => '');
}

async function mergeNodeShapes(seq: number, ep: string, promise: Promise<string>): Promise<void> {
  const ttl = await promise;
  if (seq !== seqNumber || !ttl || !ttl.trim()) return;
  await graphReady;
  if (seq !== seqNumber) return;
  const g = graph();
  if (!g) return;
  setLazyLoaded((l) => [...l, { iri: FORM_SHAPES_KEY, ttl, ep }]);
  addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
  setGraphVersion((v) => v + 1);
  const classes = coveredClassesOf(g,
    [...readShapesFn(g), ...bundledShapes()]);
  await Promise.all([
    countCoveredNodes(seq, ep, g, classes),
    fetchMissingLabels(seq, ep, g, classes),
  ]);
}

async function fetchMissingLabels(
  seq: number, ep: string, g: Graph, classes: Set<string>,
): Promise<void> {
  try {
    const unnamed = [...coveredNodesFrom(g, classes).iris]
      .filter((iri) => !hasOwnName(g, iri));
    const q = nodeLabelsQuery(unnamed, { excludeGraphs: lastExcludeGraphs });
    if (!q) return;
    const ttl = await sparqlConstruct(ep, q);
    if (seq !== seqNumber || !ttl || !ttl.trim()) return;
    await graphReady;
    if (seq !== seqNumber) return;
    setLazyLoaded((l) => [...l, { iri: LABELS_KEY, ttl, ep }]);
    const now = graph();
    if (!now) return;
    addSource(now, ttl, 'ttl', graphForSource({ url: ep }, 0));
    setGraphVersion((v) => v + 1);
    rebuildFromGraph();
  } catch {
  }
}

async function countCoveredNodes(
  seq: number, ep: string, g: Graph, classes: Set<string>,
): Promise<void> {
  try {
    const fromFile = coveredNodesFrom(g, classes,
      { skipGraphs: [String(graphForSource({ url: ep }, 0))] });
    const q = coveredCountQuery(classes, {
      excludeGraphs: lastExcludeGraphs, excludeNodes: fromFile.iris,
    });
    if (!q) return;
    const rows = await sparqlSelect(ep, q);
    if (seq !== seqNumber) return;
    const n = parseInt((rows[0] && rows[0].n && rows[0].n.value) || '', 10);
    if (!Number.isFinite(n)) return;
    const total = n + fromFile.iris.size + fromFile.blanks;
    if (total > 0) setCoveredCount(total);
  } catch {
  }
}

async function loadFromEndpoint(
  seq: number, ep: string, policyScope: string | null, options: BuildOptions,
): Promise<void> {
  const shapes = formShapesTtl(ep);
  try {
    if (policyScope) {
      const ttl = await sparqlConstruct(ep,
        policyDetailQuery(policyScope, { excludeGraphs: lastExcludeGraphs }));
      if (seq !== seqNumber) return;
      await processSources(seq, withBase([{
        name: `${ep} (policy-detail)`, url: ep, content: ttl, format: 'ttl', fromSparql: true,
      }]), withBaseErrors([]), options);
      return;
    }
    await loadPolicyList(seq, ep, options);
  } catch (e) {
    setListError('endpoint');
    reportError(seq, { url: ep, message: e instanceof Error ? e.message : String(e) });
  } finally {
    await mergeNodeShapes(seq, ep, shapes);
  }
}

export function loadCorpus(params: {
  src: string[];
  ttl?: string[];
  sparql?: string | null;
  policyScope?: string | null;
  setScope?: string | null;
  lang?: string;
  excludeGraphs?: string[];
}): void {
  const seq = ++seqNumber;
  const urls = sourcesToLoad({
    src: params.src || [],
    ttl: params.ttl || [],
    sparql: params.sparql ?? null,
    scope: params.policyScope ?? params.setScope ?? null,
  });
  const setScope = params.setScope ?? null;
  const policyScope = params.policyScope ?? null;
  const ep = params.sparql || null;
  const lang = params.lang ?? getLang();
  const options: BuildOptions = { setScope, policyScope, lang };
  lastSetScope = setScope;
  lastPolicyScope = policyScope;
  lastRawExclude = params.excludeGraphs;
  setGraph(null);
  graphReady = Promise.resolve();
  setErrors([]);
  baseSources = [];
  baseErrors = [];
  noteEndpoint(ep);
  setEndpointIsSource(false);
  setListPhase(null);
  setListError(null);
  setCompatIndex(false);
  setLazyLoaded([]);
  levelLoaded.clear();
  detailLoaded.clear();
  detailBezig.clear();
  nodeFormLoaded.clear();
  setCoveredCount(null);

  if (!urls.length && !ep && !(policyScope || setScope)) {
    setModel(null); setSources([]); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setLoadStatus('empty');
    return;
  }
  setLoadStatus('loading');
  if (urls.length) {
    setLoadNotice('load.sources');
    void loadFiles(seq, urls, options);
    return;
  }
  if (ep) {
    setLoadNotice('load.queryEndpointAt');
    setEndpointIsSource(true);
    void loadFromEndpoint(seq, ep, policyScope, options);
    return;
  }
  setLoadNotice('load.source');
  void loadScopeSource(seq, (policyScope || setScope)!, options);
}

const detailLoaded = new Set<string>();
const detailBezig = new Map<string, Promise<boolean>>();

export function detailNeeded(pol: {
  iri?: string; anon?: boolean; stub?: boolean;
  permissions?: unknown[]; prohibitions?: unknown[]; obligations?: unknown[];
} | null): boolean {
  if (!endpoint() || !pol || !pol.iri || pol.anon || pol.stub) return false;
  if (detailLoaded.has(pol.iri)) return false;
  return !((pol.permissions && pol.permissions.length)
    || (pol.prohibitions && pol.prohibitions.length)
    || (pol.obligations && pol.obligations.length));
}

export async function fetchDetail(
  iri: string, options: { rebuildModel?: boolean } = {},
): Promise<boolean> {
  const ep = endpoint();
  if (!iri || !ep || detailLoaded.has(iri)) return false;
  const bezig = detailBezig.get(iri);
  if (bezig) return bezig;
  const seq = seqNumber;
  const p = (async () => {
    const ttl = await sparqlConstruct(ep,
      policyDetailQuery(iri, { excludeGraphs: lastExcludeGraphs }));
    await graphReady;
    if (seq !== seqNumber) return false;
    const g = graph();
    if (!g) throw new Error(t('load.graph'));
    setLazyLoaded((l) => [...l, { iri, ttl, ep }]);
    addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
    detailLoaded.add(iri);
    setGraphVersion((v) => v + 1);
    if (options.rebuildModel !== false) rebuildFromGraph();
    return true;
  })();
  detailBezig.set(iri, p);
  try { return await p; } finally { detailBezig.delete(iri); }
}

export async function fetchDetails(iris: readonly string[]): Promise<boolean> {
  const list = [...new Set(iris.filter(Boolean))];
  if (!list.length || !endpoint()) return false;
  const seq = seqNumber;
  const out = await Promise.all(
    list.map((iri) => fetchDetail(iri, { rebuildModel: false })));
  if (seq !== seqNumber) return false;
  if (out.some(Boolean)) rebuildFromGraph();
  return out.some(Boolean);
}

function rebuildFromGraph(): void {
  const g = graph();
  if (!g) return;
  const m = buildModel(g);
  const n = buildNav(m);
  setModel(m);
  setNav(() => n);
  setScopedNav(() => ownScoping(n, currentScope()));
}

export interface Invalidation {
  mode: 'targeted' | 'full';
  policies: string[];
  reason: string;
}

function policyIris(m: Model): Set<string> {
  const out = new Set<string>();
  for (const bucket of [m.offers, m.agreements, m.sets]) {
    for (const p of (bucket || []) as { iri?: string; anon?: boolean }[]) {
      if (p.iri && !p.anon) out.add(p.iri);
    }
  }
  return out;
}

const sameSet = (a: Set<string>, b: Set<string>): boolean => a.size === b.size
  && [...a].every((x) => b.has(x));

function equalValue(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((x, i) => equalValue(x, b[i]));
  }
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false;
  const ao = a as Record<string, unknown>;
  const bo = b as Record<string, unknown>;
  const keys = Object.keys(ao);
  if (keys.length !== Object.keys(bo).length) return false;
  return keys.every((k) => equalValue(ao[k], bo[k]));
}

interface NavRow { id?: string; label?: string; children?: NavRow[] }

function reuseRows(prev: NavRow[] | null, next: NavRow[]): NavRow[] {
  if (!prev || !prev.length) return next;
  const byId = new Map<string, NavRow>();
  for (const r of prev) if (r && r.id) byId.set(r.id, r);
  return next.map((r) => {
    const o = r && r.id ? byId.get(r.id) : undefined;
    if (!o) return r;
    const children = reuseRows(o.children || null, r.children || []);
    const candidate = children === r.children ? r : { ...r, children };
    return equalValue(o, candidate) ? o : candidate;
  });
}

function setTree(m: Model, oldNav: Nav): void {
  const n = buildNav(m);
  const paired = (Array.isArray(oldNav) && Array.isArray(n))
    ? reuseRows(oldNav as NavRow[], n as NavRow[]) : n;
  setModel(m);
  setNav(() => paired as Nav);
  setScopedNav(() => ownScoping(paired as Nav, currentScope()));
}

function fullRebuild(reason: string, loud: boolean): Invalidation {
  if (loud) console.warn(`corpus: full rebuild after a mutation — ${reason}`);
  const g = graph();
  if (g) {
    setTree(buildModel(g), nav());
    setGraphVersion((v) => v + 1);
  }
  return { mode: 'full', policies: [], reason };
}

// Falls back to a full rebuild LOUDLY when the assignment is incomplete. Datasets,
// artifacts and version containers are re-read on every rebuild, so the boundary
// runs along "what comes out of the reuse", not along "what is a policy".
export function invalidate(delta: Delta): Invalidation {
  const g = graph();
  const m = model();
  if (!g || !m) return { mode: 'full', policies: [], reason: 'no graph or model' };
  const quads = [...(delta.added || []), ...(delta.removed || [])];
  if (!quads.length) return fullRebuild('empty delta', false);

  const previousIris = policyIris(m);
  const assignment = touchedPolicies(g, delta, previousIris);
  const touched = assignment.policies;
  if (!touched) {
    return fullRebuild(assignment.reason === 'budget'
      ? 'the attribution ran out of its node budget'
      : 'mutation outside the known cards', true);
  }

  const next = buildModel(g, { reuse: m, only: new Set(touched) });
  if (!sameSet(previousIris, policyIris(next))) {
    return fullRebuild('the set of policies changed', true);
  }
  setTree(next, nav());
  setGraphVersion((v) => v + 1);
  return { mode: 'targeted', policies: touched, reason: '' };
}

const EAGER_DETAIL_MAX = 20;

export async function fetchCardDetails(seq?: number): Promise<void> {
  const m = model() as unknown as { offers?: unknown[]; agreements?: unknown[] } | null;
  if (!endpoint() || !m) return;
  const offers = (m.offers || []).filter((p) => detailNeeded(p as never))
    .slice(0, EAGER_DETAIL_MAX);
  const agreements = (m.agreements || []).filter((p) => detailNeeded(p as never));
  const pols = (offers.length + agreements.length <= EAGER_DETAIL_MAX
    ? [...offers, ...agreements] : offers) as Array<{ iri: string }>;
  if (!pols.length) return;
  await Promise.all(pols.map((p) => fetchDetail(p.iri, { rebuildModel: false })
    .catch(() => false)));
  if (seq !== undefined && seq !== seqNumber) return;
  rebuildFromGraph();
}

const levelLoaded = new Set<string>();

export async function fetchCollectionLevel(iri: string): Promise<boolean> {
  const ep = endpoint();
  if (!iri || !ep || levelLoaded.has(iri)) return false;
  levelLoaded.add(iri);
  try {
    const ttl = await sparqlConstruct(ep,
      collectionLevelQuery(iri, { excludeGraphs: lastExcludeGraphs }));
    await graphReady;
    const g = graph();
    if (!g) throw new Error(t('load.graph'));
    if (!ttl || !ttl.trim()) return false;
    setLazyLoaded((l) => [...l, { iri, ttl, ep }]);
    addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
    setGraphVersion((v) => v + 1);
    return true;
  } catch {
    levelLoaded.delete(iri);
    return false;
  }
}

