export const lazyLoadedNodes: () => readonly { iri: string; ttl: string; ep: string }[] =
  lazyLoaded;

export function setSourcesList(list: Source[]): void {
  setSources(list);
}

export async function reloadSources(list: Source[]): Promise<void> {
  const seq = ++seqNumber;
  const options: BuildOptions = {
    setScope: lastSetScope, policyScope: lastPolicyScope, lang: getLang(),
  };
  setLoadStatus('loading');
  setErrors([]);
  baseSources = list.filter((b) => !b.fromSparql);
  baseErrors = [];
  if (!list.length && endpoint()) {
    setSources([]);
    baseSources = [];
    setLoadNotice('load.queryEndpointAt');
    setEndpointIsSource(true);
    await loadFromEndpoint(seq, endpoint()!, lastPolicyScope, options);
    return;
  }
  if (!list.length) {
    setSources([]); setModel(null); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setLoadStatus('empty');
    return;
  }
  setLoadNotice('load.sources');
  await processSources(seq, list, [], options);
}

let preprocessing: ((list: Source[]) => Promise<Source[]>) | null = null;

export function registerSourcePreprocessing(
  fn: ((list: Source[]) => Promise<Source[]>) | null,
): void {
  preprocessing = fn;
}

// A registered preprocessing step that never SETTLES is caught by no catch and
// closed by no finally; it sits on the critical path of document assembly, so
// without this floor no card ever appears — no error, just "loading".
const PREPROCESS_DEADLINE_MS = 8000;

interface Preprocessed { list: Source[]; error: CorpusError | null }

async function preprocessed(list: Source[]): Promise<Preprocessed> {
  if (!preprocessing) return { list, error: null };
  let timer: ReturnType<typeof setTimeout> | null = null;
  const TOO_SLOW = Symbol('preprocessing too slow');
  try {
    const limit = new Promise<typeof TOO_SLOW>((r) => {
      timer = setTimeout(() => r(TOO_SLOW), PREPROCESS_DEADLINE_MS);
    });
    const out = await Promise.race([preprocessing(list), limit]);
    if (out === TOO_SLOW) {
      return { list, error: { message: t('err.sourceLayerSlow') } };
    }
    return { list: out, error: null };
  } catch {
    return { list, error: null };
  } finally {
    if (timer !== null) clearTimeout(timer);
  }
}
