import { registerPrefixes } from './parse.js';

export const WORKER_BYTE_THRESHOLD = 1_500_000;

export function totalSourceBytes(sources) {
  return (sources || []).reduce((n, s) => n + (s && s.content ? s.content.length : 0), 0);
}

export function useWorkerFor(sources) {
  return typeof Worker !== 'undefined' && totalSourceBytes(sources) > WORKER_BYTE_THRESHOLD;
}

export { createStore, hydrateInto } from './graph-transfer.js';

import { profile } from './profile.js';

// The worker sends the model FIRST and the graph after (onStore); once the model
// has arrived the promise must not be rejected any more.
export function loadSourcesInWorker(sources, { setScope = null, lang = null, onProgress = null, onStore = null } = {}) {
  return new Promise((resolve, reject) => {
    let worker;
    try {
      worker = new Worker(new URL('./model-worker.js', import.meta.url), { type: 'module' });
    } catch (e) { reject(e); return; }
    let modelSeen = false;
    const fail = (message) => {
      worker.terminate();
      if (modelSeen) { if (onStore) onStore(null); }
      else reject(new Error(message));
    };
    worker.onerror = (e) => fail(e && e.message ? e.message : 'worker failed to start');
    worker.onmessage = (ev) => {
      const msg = ev.data || {};
      if (msg.type === 'progress') { if (!modelSeen && onProgress) onProgress(msg); return; }
      if (msg.type === 'model') {
        modelSeen = true;
        registerPrefixes(msg.prefixes);
        resolve(msg);
        return;
      }
      if (msg.type === 'store') {
        worker.terminate();
        if (onStore) onStore(msg);
        return;
      }
      if (msg.type === 'error') fail(msg.message);
    };
    worker.postMessage({ sources, setScope, lang, profile: profile() });
  });
}

export { termOf as asTerm } from './term.js';
