
import { detectFormat } from './parse.js';

export function sourceAddressError(url, base) {
  const s = String(url || '').trim();
  if (!s) return 'empty source address';
  const from = base
    || (typeof location !== 'undefined' && location.href ? location.href : 'https://x.invalid/');
  let u;
  try {
    u = new URL(s, from);
  } catch {
    return 'not a valid address: ' + s;
  }
  if (u.protocol === 'http:' || u.protocol === 'https:') return null;
  return `source address with an unsupported scheme (${u.protocol}): ${s}`
    + ' — a source has to be reachable over http(s)';
}

function looksLikeHtml(content) {
  const head = String(content || '').trimStart().slice(0, 200).toLowerCase();
  return head.startsWith('<!doctype html') || head.startsWith('<html') || head.startsWith('<?xml-stylesheet');
}

export function guessSourceKind(url) {
  const clean = String(url || '').trim().replace(/[?#].*$/, '');
  if (!clean) return null;
  if (/\.(ttl|turtle|nt|jsonld|json)$/i.test(clean)) return 'data';
  if (/\/(sparql|query)$/i.test(clean)) return 'sparql';
  return null;
}

async function askProbe(url, fetchImpl) {
  const res = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/sparql-results+json',
    },
    body: 'query=' + encodeURIComponent('ASK {}'),
  });
  if (!res.ok) return false;
  try {
    const json = await res.json();
    return typeof json === 'object' && json !== null && typeof json.boolean === 'boolean';
  } catch { return false; }
}

// Undecided counts as a FILE: an endpoint that also serves Turtle on GET gives no
// explicit signal, and only a successful probe may promote it.
export async function detectSource(url, fetchImpl) {
  const doFetch = fetchImpl || globalThis.fetch;
  const schemeError = sourceAddressError(url);
  if (schemeError) return { kind: 'error', url, code: 'schema', message: schemeError };
  const guess = guessSourceKind(url);
  if (guess === 'sparql') return { kind: 'sparql', url };

  let networkFailed = false;
  if (guess !== 'data') {
    try {
      if (await askProbe(url, doFetch)) return { kind: 'sparql', url };
    } catch { networkFailed = true; }
  }
  try {
    const res = await doFetch(url);
    if (!res.ok) {
      return { kind: 'error', url, code: 'unsupported', message: 'HTTP ' + res.status + ' at ' + url };
    }
    const content = await res.text();
    const format = detectFormat(url, content);
    if (format === 'rdfxml') {
      return { kind: 'error', url, code: 'unsupported', message: 'format not supported (RDF/XML): ' + url };
    }
    if (looksLikeHtml(content)) {
      return {
        kind: 'error', url, code: 'unsupported',
        message: 'this address serves a web page, not RDF: ' + url,
      };
    }
    return { kind: 'data', url, content, format };
  } catch (e) {
    void networkFailed;
    return {
      kind: 'error', url, code: 'unreachable',
      message: 'source not reachable (CORS or offline?): ' + url + ' — ' + e.message,
    };
  }
}

export async function partitionSources(urls, fetchImpl) {
  const data = [];
  const endpoints = [];
  const errors = [];
  for (const u of urls || []) {
    const r = await detectSource(u, fetchImpl);
    if (r.kind === 'sparql') endpoints.push(r.url);
    else if (r.kind === 'data') data.push({ name: u, url: u, content: r.content, format: r.format });
    else errors.push({ url: u, code: r.code, message: r.message });
  }
  return { data, endpoints, errors };
}
