
import {
  TEMPORAL_VOCABS, VERSION_DATING_PREDS, SKELETON_CONTAINER_CLASS,
  SKELETON_MEMBER_PRED, SKELETON_COUNT_PRED,
} from './temporal.js';
import { langRank, getLang } from './i18n.js';
import * as N3 from 'n3';

const { quad } = N3.DataFactory;

const ODRL = 'http://www.w3.org/ns/odrl/2/';
const DCT = 'http://purl.org/dc/terms/';
const DCAT = 'http://www.w3.org/ns/dcat#';
const SCHEMA = 'https://schema.org/';

export const DEFAULT_EXCLUDE_GRAPHS = [];

const PREFIXES_SPARQL = `PREFIX odrl: <http://www.w3.org/ns/odrl/2/>
PREFIX dct:  <http://purl.org/dc/terms/>
PREFIX rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX schema: <https://schema.org/>
`;

async function sparqlPost(endpoint, query, accept, fetchImpl) {
  const doFetch = fetchImpl || globalThis.fetch;
  const res = await doFetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: accept,
    },
    body: 'query=' + encodeURIComponent(query),
  });
  if (!res.ok) {
    let detail = '';
    try { detail = (await res.text()).slice(0, 200); } catch {  }
    throw new Error(`SPARQL HTTP ${res.status}${detail ? ' — ' + detail : ''}`);
  }
  return res;
}

export async function sparqlSelect(endpoint, query, fetchImpl) {
  const res = await sparqlPost(endpoint, query, 'application/sparql-results+json', fetchImpl);
  const json = await res.json();
  return (json && json.results && json.results.bindings) || [];
}

export async function sparqlConstruct(endpoint, query, fetchImpl) {
  const res = await sparqlPost(endpoint, query, 'text/turtle', fetchImpl);
  return res.text();
}

function isBlank(term) {
  return Boolean(term) && term.termType === 'BlankNode';
}

// SPARQL 1.1 Update forbids blank nodes in DELETE/INSERT DATA: they are skipped
// and counted, never silently dropped.
function groundQuads(quads, label) {
  const kept = [];
  let skipped = 0;
  for (const q of quads) {
    if (isBlank(q.subject) || isBlank(q.object)) { skipped++; continue; }
    kept.push(q);
  }
  if (skipped) {
    console.warn(`SPARQL Update: skipped ${skipped} ${label} triple(s) with a`
      + ' blank node (DELETE/INSERT DATA allows none)');
  }
  return { kept, skipped };
}

const LANGUAGE_TAG = /^[A-Za-z]+(-[A-Za-z0-9]+)*$/;

function assertSafeLanguage(tag) {
  if (!LANGUAGE_TAG.test(String(tag))) throw new Error('invalid language tag for SPARQL: ' + tag);
}

// The vendored N3 writer does not escape < or > in a NamedNode, so an IRI with a
// > would inject bare SPARQL into an update to a live endpoint. Such an IRI is
// reachable from an ordinary UI text field, so it is refused here, just before
// sending.
function assertSafeTerm(term) {
  if (!term) return;
  if (term.termType === 'NamedNode') {
    iriRef(term.value);
  } else if (term.termType === 'Literal') {
    if (term.language) assertSafeLanguage(term.language);
    if (term.datatype) assertSafeTerm(term.datatype);
  }
}

function tripleBlock(quads) {
  const w = new N3.Writer();
  const safe = quads.map((q) => {
    assertSafeTerm(q.subject);
    assertSafeTerm(q.predicate);
    assertSafeTerm(q.object);
    return quad(q.subject, q.predicate, q.object);
  });
  return w.quadsToString(safe);
}

export function updateStatements({ added = [], removed = [] } = {}) {
  const rem = groundQuads(removed, 'DELETE');
  const add = groundQuads(added, 'INSERT');
  const parts = [];
  if (rem.kept.length) parts.push('DELETE DATA {\n' + tripleBlock(rem.kept) + '}');
  if (add.kept.length) parts.push('INSERT DATA {\n' + tripleBlock(add.kept) + '}');
  return { query: parts.join(';\n'), skipped: rem.skipped + add.skipped };
}

export async function sparqlUpdate(endpoint, update, fetchImpl) {
  const doFetch = fetchImpl || globalThis.fetch;
  const res = await doFetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'update=' + encodeURIComponent(update),
  });
  if (!res.ok) {
    let detail = '';
    try { detail = (await res.text()).slice(0, 200); } catch {  }
    throw new Error(`SPARQL update HTTP ${res.status}${detail ? ' — ' + detail : ''}`);
  }
}

function iriRef(iri) {
  const s = String(iri || '');
  if (!/^[^<>"{}|^`\\\s]+$/.test(s)) throw new Error('invalid IRI for SPARQL: ' + s);
  return '<' + s + '>';
}

function graphFilter(gVar, excludeGraphs) {
  if (!excludeGraphs || !excludeGraphs.length) return '';
  return `FILTER(${gVar} NOT IN (${excludeGraphs.map(iriRef).join(', ')}))`;
}

const MEMBER_VOCAB = TEMPORAL_VOCABS.find((v) => v.id === 'prov');
function memberUnion(cVar, vVar) {
  const alts = [
    ...MEMBER_VOCAB.memberPreds.map((p) => `{ ${cVar} <${p}> ${vVar} }`),
    ...MEMBER_VOCAB.inverseMemberPreds.map((p) => `{ ${vVar} <${p}> ${cVar} }`),
  ];
  if (alts.length === 1) return alts[0].replace(/^\{ | \}$/g, '') + ' .';
  return alts.join(' UNION ');
}

const VERSION_DATING_ALT = VERSION_DATING_PREDS.map((p) => `<${p}>`).join('|');

const validityOptionals = (sVar, nodeVar, fromVar, toVar) => `  OPTIONAL { ${sVar} schema:validFrom ${fromVar}_s }
  OPTIONAL { ${sVar} schema:validThrough ${toVar}_s }
  OPTIONAL {
    ${sVar} dct:valid ${nodeVar} .
    OPTIONAL { ${nodeVar} dcat:startDate ${fromVar}_n }
    OPTIONAL { ${nodeVar} dcat:endDate ${toVar}_n }
  }
  BIND(COALESCE(${fromVar}_s, ${fromVar}_n) AS ${fromVar})
  BIND(COALESCE(${toVar}_s, ${toVar}_n) AS ${toVar})`;

export function policyListQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?policy ?kind
       (SAMPLE(?t)   AS ?title)
       (SAMPLE(?a)   AS ?assignee) (SAMPLE(?al) AS ?assigneeLabel)
       (SAMPLE(?c)   AS ?container) (SAMPLE(?ct) AS ?containerTitle)
       (SAMPLE(?vc)  AS ?versionCount)
       (SAMPLE(?iss) AS ?issued)
       (SAMPLE(?vf)  AS ?validFrom) (SAMPLE(?vt) AS ?validTo)
       (SAMPLE(?vn)  AS ?valid)
       (SAMPLE(?rev) AS ?revisionOf)
       (SAMPLE(?ofX) AS ?offerRef)
       (SAMPLE(?rqX) AS ?requestRef)
       (SAMPLE(?ansX) AS ?answeredByRef)
WHERE {
  VALUES (?type ?kind) { (odrl:Set "set") (odrl:Offer "offer") (odrl:Agreement "agreement") (odrl:Request "request") }
  ?policy a ?type .
  FILTER(isIRI(?policy))
  OPTIONAL { ?policy dct:title ?t }
  OPTIONAL {
    { ?policy odrl:assignee ?a } UNION { ?policy odrl:permission/odrl:assignee ?a }
    OPTIONAL { ?a rdfs:label|skos:prefLabel ?al }
  }
  OPTIONAL {
    { SELECT ?policy (SAMPLE(?cX) AS ?c) (SAMPLE(?ctX) AS ?ct)
             (SAMPLE(?vcX) AS ?vc)
      WHERE {
        { SELECT ?cX (COUNT(DISTINCT ?v) AS ?vcX) WHERE {
            ${memberUnion('?cX', '?v')}
            FILTER(isIRI(?v))
            # A version is a TYPED policy OR a document version (stub): a
            # member that carries no ODRL type but does carry version data.
            # The same check as readTemporalContainers. Without the stub branch
            # a register that keeps superseded versions as bare entities counts
            # every agreement as one version, and the arrows stay away on every
            # collapsed card. The type-check alternative without a subquery
            # measured an order of magnitude slower, so this form stays.
            { VALUES ?vt { odrl:Set odrl:Offer odrl:Agreement odrl:Request } ?v a ?vt }
            UNION
            { ?v ${VERSION_DATING_ALT} ?vd }
          } GROUP BY ?cX }
        ${memberUnion('?cX', '?policy')}
        OPTIONAL { ?cX dct:title ?ctX }
      } GROUP BY ?policy }
  }
  # Dating of the version: dct:issued (what the version navigator shows) and the
  # validity period. Without these branches the chip showed a dash everywhere in
  # list mode.
  OPTIONAL { ?policy dct:issued ?iss }
${validityOptionals('?policy', '?vn', '?vf', '?vt')}
  OPTIONAL { ?policy prov:wasRevisionOf ?rev }
  # Agreement -> Offer link (SAMPLE: one per policy), so the skeleton graph can
  # fill the back-reference list on an offer card. The type check keeps
  # legal-basis and source references out.
  OPTIONAL { ?policy prov:wasDerivedFrom ?ofX . ?ofX a odrl:Offer }
  # Agreement -> Request link, along the same predicate and with the same type
  # check, but in its OWN column: an agreement usually carries BOTH, and one
  # SAMPLE would drop one of them at random. This lets a request card show its
  # decision row without the agreement's detail being loaded; without this
  # branch every request looked unanswered.
  OPTIONAL { ?policy prov:wasDerivedFrom ?rqX . ?rqX a odrl:Request }
  # The same relation once more, but REVERSED: which agreement points at THIS
  # policy? On a request row that is the agreement it was decided in, which is
  # what the fixed row on the request card hangs on.
  #
  # Why the column above is not enough: it is a SAMPLE PER AGREEMENT, and an
  # agreement often comes from SEVERAL requests. The unchosen ones then looked
  # unanswered, while this direction reaches them all. The other way round the
  # SAMPLE is safe: one request leads to one decision.
  # Measured (25-8, Fuseki, 3 rounds, /brp-ap) with/without: 0.47/0.56 s — within
  # the noise, and the answer grows only marginally.
  OPTIONAL { ?ansX prov:wasDerivedFrom ?policy . ?ansX a odrl:Agreement }
}
GROUP BY ?policy ?kind
`;
}

// The five flat queries exist for their SHAPE: no nested sub-SELECT, because
// streaming evaluators break on those. A handy subquery undoes the whole
// compatibility path.
export function flatPolicyRowsQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?policy ?kind ?title ?assignee ?assigneeLabel
WHERE {
  VALUES (?type ?kind) { (odrl:Set "set") (odrl:Offer "offer") (odrl:Agreement "agreement") (odrl:Request "request") }
  ?policy a ?type .
  FILTER(isIRI(?policy))
  OPTIONAL { ?policy dct:title ?title }
  OPTIONAL {
    { ?policy odrl:assignee ?assignee } UNION { ?policy odrl:permission/odrl:assignee ?assignee }
    OPTIONAL { ?assignee rdfs:label|skos:prefLabel ?assigneeLabel }
  }
}
`;
}

export function flatMembershipQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?container ?policy ?containerTitle
WHERE {
  VALUES ?type { odrl:Set odrl:Offer odrl:Agreement odrl:Request }
  ?policy a ?type .
  ${memberUnion('?container', '?policy')}
  FILTER(isIRI(?container) && isIRI(?policy))
  OPTIONAL { ?container dct:title ?containerTitle }
}
`;
}

export function flatVersionCountQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?container (COUNT(DISTINCT ?v) AS ?n)
WHERE {
  ${memberUnion('?container', '?v')}
  FILTER(isIRI(?container) && isIRI(?v))
  { VALUES ?vt { odrl:Set odrl:Offer odrl:Agreement odrl:Request } ?v a ?vt }
  UNION
  { ?v ${VERSION_DATING_ALT} ?vd }
}
GROUP BY ?container
`;
}

export function flatVersionMetaQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?policy ?issued ?validFrom ?validTo ?valid ?revisionOf
WHERE {
  VALUES ?type { odrl:Set odrl:Offer odrl:Agreement odrl:Request }
  ?policy a ?type .
  FILTER(isIRI(?policy))
  OPTIONAL { ?policy dct:issued ?issued }
${validityOptionals('?policy', '?valid', '?validFrom', '?validTo')}
  OPTIONAL { ?policy prov:wasRevisionOf ?revisionOf }
}
`;
}

export function flatOfferRefQuery() {
  return `${PREFIXES_SPARQL}
SELECT DISTINCT ?policy ?offer
WHERE {
  VALUES ?type { odrl:Set odrl:Offer odrl:Agreement odrl:Request }
  ?policy a ?type .
  ?policy prov:wasDerivedFrom ?offer .
  ?offer a odrl:Offer .
  FILTER(isIRI(?policy))
}
`;
}

export function flatRequestRefQuery() {
  return `${PREFIXES_SPARQL}
SELECT DISTINCT ?policy ?request
WHERE {
  VALUES ?type { odrl:Set odrl:Offer odrl:Agreement odrl:Request }
  ?policy a ?type .
  ?policy prov:wasDerivedFrom ?request .
  ?request a odrl:Request .
  FILTER(isIRI(?policy))
}
`;
}

export function flatAnsweredByQuery() {
  return `${PREFIXES_SPARQL}
SELECT DISTINCT ?policy ?agreement
WHERE {
  VALUES ?type { odrl:Set odrl:Offer odrl:Agreement odrl:Request }
  ?policy a ?type .
  ?agreement prov:wasDerivedFrom ?policy .
  ?agreement a odrl:Agreement .
  FILTER(isIRI(?policy))
}
`;
}

export function mergeFlatIndex(rows, membership, counts, meta, offerRefs,
  { lang = null, requestRefs = [], answeredByRefs = [] } = {}) {
  const val = (b) => (b ? b.value : null);
  const L = lang || getLang();
  const better = (cur, next) => !cur
    || langRank(next['xml:lang'] || '', L) < langRank(cur['xml:lang'] || '', L);

  const contByPolicy = new Map();
  for (const r of membership || []) {
    const p = val(r && r.policy);
    if (!p || !r.container) continue;
    let e = contByPolicy.get(p);
    if (!e) { e = { container: r.container, containerTitle: null }; contByPolicy.set(p, e); }
    if (r.containerTitle && r.container.value === e.container.value
      && better(e.containerTitle, r.containerTitle)) {
      e.containerTitle = r.containerTitle;
    }
  }

  const countByContainer = new Map();
  for (const r of counts || []) {
    const c = val(r && r.container);
    if (!c || !r.n) continue;
    if (!countByContainer.has(c)) countByContainer.set(c, r.n);
  }

  const META_FIELDS = ['issued', 'validFrom', 'validTo', 'valid', 'revisionOf'];
  const metaByPolicy = new Map();
  for (const r of meta || []) {
    const p = val(r && r.policy);
    if (!p) continue;
    let e = metaByPolicy.get(p);
    if (!e) { e = {}; metaByPolicy.set(p, e); }
    for (const f of META_FIELDS) if (!e[f] && r[f]) e[f] = r[f];
  }

  const offerByPolicy = new Map();
  for (const r of offerRefs || []) {
    const p = val(r && r.policy);
    if (!p || !r.offer) continue;
    if (!offerByPolicy.has(p)) offerByPolicy.set(p, r.offer);
  }
  const reqByPolicy = new Map();
  for (const r of requestRefs || []) {
    const p = val(r && r.policy);
    if (!p || !r.request) continue;
    if (!reqByPolicy.has(p)) reqByPolicy.set(p, r.request);
  }
  const ansByPolicy = new Map();
  for (const r of answeredByRefs || []) {
    const p = val(r && r.policy);
    if (!p || !r.agreement) continue;
    if (!ansByPolicy.has(p)) ansByPolicy.set(p, r.agreement);
  }

  const out = [];
  const byKey = new Map();
  for (const r of rows || []) {
    if (!r || !r.policy) continue;
    const key = r.policy.value + '\u0000' + (val(r.kind) || '');
    let row = byKey.get(key);
    if (!row) {
      row = { policy: r.policy };
      if (r.kind) row.kind = r.kind;
      byKey.set(key, row);
      out.push(row);
    }
    if (r.title && better(row.title, r.title)) row.title = r.title;
    if (!row.assignee && r.assignee) {
      row.assignee = r.assignee;
      if (r.assigneeLabel) row.assigneeLabel = r.assigneeLabel;
    } else if (row.assignee && r.assigneeLabel
      && r.assignee && r.assignee.value === row.assignee.value
      && better(row.assigneeLabel, r.assigneeLabel)) {
      row.assigneeLabel = r.assigneeLabel;
    }
  }
  for (const row of out) {
    const p = row.policy.value;
    const c = contByPolicy.get(p);
    if (c) {
      row.container = c.container;
      if (c.containerTitle) row.containerTitle = c.containerTitle;
      const n = countByContainer.get(c.container.value);
      if (n) row.versionCount = n;
    }
    const m = metaByPolicy.get(p);
    if (m) for (const f of META_FIELDS) if (m[f]) row[f] = m[f];
    const o = offerByPolicy.get(p);
    if (o) row.offerRef = o;
    const rq = reqByPolicy.get(p);
    if (rq) row.requestRef = rq;
    const ans = ansByPolicy.get(p);
    if (ans) row.answeredByRef = ans;
  }
  return out;
}

export function isEndpointTimeout(err) {
  const msg = String((err && err.message) || err || '');
  return /SPARQL HTTP 5\d\d/.test(msg) || /\btimed out\b|\btimeout\b/i.test(msg);
}

export async function decomposedIndexRows(endpoint, fetchImpl, { lang = null } = {}) {
  const [rows, membership, counts, meta, offerRefs, requestRefs, answeredByRefs] = await Promise.all([
    sparqlSelect(endpoint, flatPolicyRowsQuery(), fetchImpl),
    sparqlSelect(endpoint, flatMembershipQuery(), fetchImpl),
    sparqlSelect(endpoint, flatVersionCountQuery(), fetchImpl),
    sparqlSelect(endpoint, flatVersionMetaQuery(), fetchImpl),
    sparqlSelect(endpoint, flatOfferRefQuery(), fetchImpl),
    sparqlSelect(endpoint, flatRequestRefQuery(), fetchImpl),
    sparqlSelect(endpoint, flatAnsweredByQuery(), fetchImpl),
  ]);
  return mergeFlatIndex(rows, membership, counts, meta, offerRefs,
    { lang, requestRefs, answeredByRefs });
}

export const FIRST_LIST_LIMIT = 60;

export function policyListFirstQuery({ limitPerKind = FIRST_LIST_LIMIT } = {}) {
  const lim = Math.max(1, limitPerKind | 0);
  const branch = (cls, kind) => `  {
    { SELECT ?policy WHERE { ?policy a ${cls} . FILTER(isIRI(?policy)) } LIMIT ${lim} }
    BIND("${kind}" AS ?kind)
  }`;
  return `${PREFIXES_SPARQL}
SELECT ?policy ?kind
       (SAMPLE(?t)  AS ?title)
       (SAMPLE(?a)  AS ?assignee) (SAMPLE(?al) AS ?assigneeLabel)
WHERE {
${branch('odrl:Set', 'set')} UNION
${branch('odrl:Offer', 'offer')} UNION
${branch('odrl:Agreement', 'agreement')} UNION
${branch('odrl:Request', 'request')}
  OPTIONAL { ?policy dct:title ?t }
  OPTIONAL {
    { ?policy odrl:assignee ?a } UNION { ?policy odrl:permission/odrl:assignee ?a }
    OPTIONAL { ?a rdfs:label|skos:prefLabel ?al }
  }
}
GROUP BY ?policy ?kind
`;
}

export function containerListQuery() {
  return `${PREFIXES_SPARQL}
SELECT ?container ?kind ?version
       (SAMPLE(?ct)  AS ?containerTitle)
       (SAMPLE(?t)   AS ?title)
       (SAMPLE(?vf)  AS ?validFrom) (SAMPLE(?vt) AS ?validTo)
       (SAMPLE(?vn)  AS ?valid)
       (SAMPLE(?iss) AS ?issued)
WHERE {
  VALUES (?typeHint ?kind) { (odrl:Set "set") (odrl:Offer "offer") (odrl:Agreement "agreement") (odrl:Request "request") }
  ?container dct:type ?typeHint .
  ${memberUnion('?container', '?version')}
  FILTER(isIRI(?container) && isIRI(?version))
  OPTIONAL { ?container dct:title ?ct }
  OPTIONAL { ?version dct:title ?t }
${validityOptionals('?version', '?vn', '?vf', '?vt')}
  OPTIONAL { ?version dct:issued ?iss }
}
GROUP BY ?container ?kind ?version
`;
}

const ODRL_NS = 'http://www.w3.org/ns/odrl/2/';
const DOMAIN_TYPED = (nodeVar, tag) => `${nodeVar} rdf:type ?dt${tag} .
      FILTER(!STRSTARTS(STR(?dt${tag}), "${ODRL_NS}"))`;

const CLOSURE_PATH = '(odrl:permission|odrl:prohibition|odrl:obligation|odrl:duty'
  + '|odrl:remedy|odrl:consequence|odrl:constraint|odrl:refinement'
  + '|odrl:action|odrl:target'
  + '|odrl:rightOperand'
  + '|dct:valid'
  + '|odrl:and|odrl:or|odrl:xone|odrl:andSequence|rdf:first|rdf:rest)*';

const VERSION_META_PREDS = 'rdf:type, dct:title, dct:issued, '
  + 'schema:validFrom, schema:validThrough, dct:valid, odrl:uid, '
  + 'prov:wasRevisionOf, prov:specializationOf, prov:wasDerivedFrom';

// SHAPE IS A MEASUREMENT, NOT STYLE. Closure plus hop as ONE property path; as
// loose triples the same query costs 1.0-1.3 s against 9 ms (ARQ, measured on a
// large register). The membership triple is bound to a collection from the
// closure and not to the predicate: bound to the predicate, one agreement
// returned 177,947 triples of which 177,412 odrl:partOf (99.7%).
export function policyDetailQuery(iri, { excludeGraphs = DEFAULT_EXCLUDE_GRAPHS } = {}) {
  const P = iriRef(iri);
  const closure = (sVar, pVar, oVar, gVar) => (excludeGraphs && excludeGraphs.length
    ? `${P} ${CLOSURE_PATH} ${sVar} .
    GRAPH ${gVar} { ${sVar} ${pVar} ${oVar} . }
    ${graphFilter(gVar, excludeGraphs)}`
    : `${P} ${CLOSURE_PATH} ${sVar} . ${sVar} ${pVar} ${oVar} .`);
  const hopPath = (suffix, cVar, gVar) => (excludeGraphs && excludeGraphs.length
    ? `${P} ${CLOSURE_PATH}${suffix} ${cVar} .
    GRAPH ${gVar} { ${cVar} ?lp ?ll . }
    ${graphFilter(gVar, excludeGraphs)}`
    : `${P} ${CLOSURE_PATH}${suffix} ${cVar} . ${cVar} ?lp ?ll .`);
  const MEMBER_HOP = '(dct:hasPart|^odrl:partOf)';
  const RULE_HOP = '(odrl:permission|odrl:prohibition|odrl:obligation|odrl:duty)';
  const COND_HOP = '(odrl:constraint|odrl:refinement)';
  const memberPath = (cVar, gVar) => hopPath('/' + MEMBER_HOP, cVar, gVar);
  const classPath = (cVar, gVar) => hopPath('/' + MEMBER_HOP + '/rdf:type', cVar, gVar);
  const memberLink = (gVar) => (excludeGraphs && excludeGraphs.length
    ? `${P} ${CLOSURE_PATH} ?ll .
    GRAPH ${gVar} { ?x odrl:partOf ?ll . }
    ${graphFilter(gVar, excludeGraphs)}`
    : `${P} ${CLOSURE_PATH} ?ll .
    ?x odrl:partOf ?ll .`);
  const REQ_HOP = 'prov:wasDerivedFrom';
  const requestPath = (suffix, gVar) => (excludeGraphs && excludeGraphs.length
    ? `${P} ${REQ_HOP} ?req . ?req a odrl:Request .
    ?req ${suffix} ?x .
    GRAPH ${gVar} { ?x ?lp ?ll . }
    ${graphFilter(gVar, excludeGraphs)}`
    : `${P} ${REQ_HOP} ?req . ?req a odrl:Request . ?req ${suffix} ?x . ?x ?lp ?ll .`);
  const REQ_RULE = '(odrl:permission|odrl:prohibition|odrl:obligation)?';
  const INHERIT_HOP = 'odrl:inheritFrom';
  const inheritClosure = (sVar, pVar, oVar, gVar) => (excludeGraphs && excludeGraphs.length
    ? `${P} ${INHERIT_HOP}/${CLOSURE_PATH} ${sVar} .
    GRAPH ${gVar} { ${sVar} ${pVar} ${oVar} . }
    ${graphFilter(gVar, excludeGraphs)}`
    : `${P} ${INHERIT_HOP}/${CLOSURE_PATH} ${sVar} . ${sVar} ${pVar} ${oVar} .`);
  return `${PREFIXES_SPARQL}
CONSTRUCT {
  ?s ?p ?o .
  ?c ?cp ?co .
  ?v ?vp ?vo .
  ?x ?lp ?ll .
}
WHERE {
  {
    # 1. closure of the policy itself
    ${closure('?s', '?p', '?o', '?g1')}
  } UNION {
    # 2. temporal container (with membership to every version)
    ${memberUnion('?c', P)}
    ?c ?cp ?co .
    # Blank objects stay out of view — a container is a flat node — WITH one
    # exception: an unmigrated graph can still carry its validity period as a
    # blank period node. The primary form is flat literals and comes along
    # anyway.
    FILTER(!isBlank(?co) || ?cp = dct:valid)
  } UNION {
    # 3. sibling versions: metadata for the version picker (expired included)
    ${memberUnion('?c2', P)}
    ${memberUnion('?c2', '?v')}
    ?v ?vp ?vo .
    FILTER(?vp IN (${VERSION_META_PREDS}))
  } UNION {
    # 3b. FALLBACK: validity period NODES of the container and of the sibling
    # versions. On data in the primary form this branch does NOTHING — the dates
    # are flat literals there and already come with branches 2 and 3. It stays
    # for unmigrated graphs and third-party data, where the object of dct:valid
    # is a blank period node: branches 2 and 3 then fetch the dct:valid TRIPLE
    # but not the dates behind it, and the version picker stood
    # without data. The policy's own period is already in branch 1 (dct:valid sits in
    # CLOSURE_PATH). Cheap: at most one node of three triples per version, and on
    # primary-form data these variables bind nowhere.
    {
      ${memberUnion('?cp1', P)}
      ?cp1 dct:valid ?x .
    } UNION {
      ${memberUnion('?cp2', P)}
      ${memberUnion('?cp2', '?vp1')}
      ?vp1 dct:valid ?x .
    }
    ?x ?lp ?ll .
  } UNION {
    # 4a. labels of touched predicates
    ${closure('?sa', '?x', '?oa', '?g4a')}
    ?x ?lp ?ll .
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title))
  } UNION {
    # 4b. labels of touched IRI objects (plus rdf:type, so the model recognises
    # e.g. wasDerivedFrom targets as an odrl:Offer and can show the
    # "fills in offer" row)
    ${closure('?sb', '?pb', '?x', '?g4b')}
    FILTER(isIRI(?x))
    ?x ?lp ?ll .
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))
  } UNION {
    # 4c. labels of the CLASSES of those IRI objects. A member list groups on
    # the member's rdf:type and shows the class label as the group heading.
    # Branch 4b does fetch that rdf:type, but the LABEL of the class itself is
    # one hop further; without this branch the heading fell back on the
    # localName, which is not a label and therefore does not move with the
    # language (B16). Deliberately written as ONE property path and
    # bound to the membership path, the same one the model reads. That is not a
    # style question: measured
    # on /brp this form costs 9 ms, while the same patterns written
    # as separate triples it tempts the engine into a plan an order of magnitude
    # more expensive.
    ${classPath('?x', '?g4c')}
    FILTER(?lp IN (rdfs:label, skos:prefLabel))
  } UNION {
    # 4d. MEMBERS via the ODRL core direction. If membership hangs on the
    # COLLECTION, every member is an object within the closure and 4b supplies
    # its label and rdf:type. If it hangs on the MEMBER (the core form), the
    # member is an object nowhere and the member list would stay empty in
    # endpoint mode. This branch therefore walks the membership path explicitly —
    # the inverse hop sits IN the property path, for the same reason as 4c — and
    # fetches exactly what the member list needs: the label, the grouping type,
    # and the membership triple itself.
    # Measured on a dataset with thousands of members: with this branch the
    # whole detail query is several times faster than with the hop inside the
    # star group.
    ${memberPath('?x', '?g4d')}
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))
  } UNION {
    # 4e. THE MEMBERSHIP TRIPLE ITSELF — the branch that matters at scale.
    #
    # As part of branch 4d's predicate filter it selected on PREDICATE and not
    # on OBJECT, so every member brought along its membership of EVERY collection
    # in the store — including the thousands of agreements the reader did not
    # open.
    #
    # MEASURED at full scale: the detail of ONE agreement was megabytes and
    # nearly 180k triples, of which 99.7% were membership triples. The smaller
    # corpus the branch-4d measurement used did not show this, because there a
    # member belongs to a handful of collections.
    #
    # THE SEMANTICS STAY. The view reads membership to group the member list of
    # the collection ON SCREEN, and that collection is by definition in this
    # closure. What drops out is membership of collections that do not exist on
    # this card — material the view never
    # aangeraakt.
    ${memberLink('?g4e')}
    BIND(odrl:partOf AS ?lp)
  } UNION {
    # 5a. SOURCE LOCATION: the anchor object of prov:hadPrimarySource on a rule.
    # Unlike the legal basis, this points at the PLACE in the source document the
    # rule comes from — typically a page anchor with its own label and a
    # reference to the document. Branch 4b supplies only that anchor's label and
    # type; here its OTHER own triples come along. Deliberately unfiltered on
    # predicate: which term a dataset uses for "page" is dataset knowledge and
    # does not belong in this generic layer. Blank objects stay out of view, as
    # in branch 2 — an anchor is a flat node.
    ${hopPath('/prov:hadPrimarySource', '?x', '?g5a')}
    FILTER(!isBlank(?ll))
  } UNION {
    # 5b. the SOURCE DOCUMENT one hop behind the location: its reference and
    # title, so the view can name the location without a second query. Limited to
    # identifying fields — the rest of a document description belongs to the
    # document, not to the rule.
    ${hopPath('/prov:hadPrimarySource/(dct:isPartOf|dct:isFormatOf)', '?x', '?g5b')}
    FILTER(?lp IN (dct:identifier, skos:notation, dct:title, rdfs:label))
  } UNION {
    # 6a. REQUEST: the odrl:Request this agreement came from, as a MINI-STUB —
    # reference, date and one minimal permission with the requester. Branch 4b
    # supplies only its label and rdf:type; this branch fetches the fields the
    # request row shows, plus the rule node the requester hangs on. Deliberately
    # FILTERED on predicate: a request that happens to be a full policy must not
    # let this detail query expand — it has its own card and therefore its own
    # detail CONSTRUCT.
    # Measured (24-8, Fuseki, 5 rounds, median) with/without these two branches,
    # Measured with a store full of requests: within the noise, and the answer
    # grows by the triples of the one request.
    ${requestPath(REQ_RULE, '?g6a')}
    FILTER(?lp IN (rdf:type, dct:identifier, skos:notation, dct:issued,
                   dct:title, rdfs:label, odrl:uid, odrl:assignee,
                   prov:wasDerivedFrom,
                   odrl:permission, odrl:prohibition, odrl:obligation))
  } UNION {
    # 6b. the REQUESTER of that request: the label of the odrl:assignee. That
    # can be an existing party IRI (whose label lives elsewhere in the graph) or
    # a party node with only an rdfs:label; both arrive here.
    ${requestPath(REQ_RULE + '/odrl:assignee', '?g6b')}
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title))
  } UNION {
    # 6c. the OFFER that request asks for. The link itself comes with branch 6a;
    # what was missing is the other SIDE: without an rdf:type on the target the
    # model does not know it is an odrl:Offer, and then the sentence is no longer
    # a request but plain provenance. The title belongs with it because the
    # sentence shows the offer's NAME.
    #
    # Shape rule as in 6a/6b: the path after ?req in ONE property path, only the
    # FETCHING graph-scoped. Deliberately filtered to the identifying fields —
    # the offer has its own card and therefore its own detail query. Measured
    # with and without this branch and the
    # widened 6a filter: /brp-ap 008001-v6 198/193 ms (1,950 KB, the same),
    # request kind: within the noise.
    ${requestPath('prov:wasDerivedFrom', '?g6c')}
    FILTER(?lp IN (rdf:type, dct:title, rdfs:label, skos:prefLabel))
  } UNION {
    # 7a. PARENT POLICY (odrl:inheritFrom, one hop) WITH its rules: the same
    # closure as branch 1, but from the parent. Unfiltered on predicate — the
    # fold row shows the parent's rules as full rule rows and therefore needs the
    # same fields as the own rules. Without inheritFrom in the graph this branch
    # binds nowhere and costs nothing.
    ${inheritClosure('?x', '?lp', '?ll', '?g7a')}
  } UNION {
    # 7b. labels and rdf:type of the IRIs touched in that parent closure:
    # without this branch the parent row reads its rules, but the action, the
    # purpose and the targets stand there as bare localNames. Same shape and
    # same
    # predicaatfilter als tak 4b, één inheritFrom-hop verderop.
    ${inheritClosure('?sc', '?pc', '?x', '?g7b')}
    FILTER(isIRI(?x))
    ?x ?lp ?ll .
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))
  } UNION {
    # 8a. COVERAGE: nodes pointing with prov:wasDerivedFrom at a RULE of this
    # policy — the machine-executable layer saying it covers that rule. Every
    # other branch walks the graph OUTwards; coverage is the only INcoming
    # direction the card needs, and without it the coverage chip stayed
    # empty in ?sparql= mode while the same source showed "covered by" five
    # times in ttl mode (found on /breda).
    #
    # The hop to the rule runs through the RULE POSITION and not through
    # "anything with an odrl:uid". That is not a detail: the policy itself also
    # carries an odrl:uid, and with that wider form the inverse hop from the
    # policy would drag in every agreement that fills in its offer (
    # one card). Nothing but a coverer points at a RULE.
    # Shape rule as in 4c/4d: the whole path in ONE property path.
    ${hopPath('/' + RULE_HOP + '/^prov:wasDerivedFrom', '?x', '?g8a')}
    FILTER(?lp IN (rdf:type, rdfs:label, skos:prefLabel, dct:title,
                   dct:description, prov:wasDerivedFrom))
  } UNION {
    # 8b. the label of the CLASS of that coverer — the chip names the kind
    # beside the name, and without this hop there stood a
    # bare localName. The same relation as 4b to 4c.
    ${hopPath('/' + RULE_HOP + '/^prov:wasDerivedFrom/rdf:type', '?x', '?g8b')}
    FILTER(?lp IN (rdfs:label, skos:prefLabel))
  } UNION {
    # 8c. COVERAGE AT CONSTRAINT LEVEL: nodes pointing with prov:wasDerivedFrom
    # at a CONSTRAINT of this policy. That is the centre of gravity of coverage —
    # a bundle mostly works out decision points; that the rule as a whole is
    # executed is only half the story. Without this branch the affordance
    # appeared in file mode and not in endpoint mode, on exactly the same
    # source.
    #
    # Same shape and same reasoning as 8a: the hop ends on the CONSTRAINT
    # POSITION and not on "anything with a label" — only what hangs in constraint
    # or refinement position can be a coverage target, and nothing but a coverer
    # points at such a node. The path runs over the whole closure, so rule,
    # action and collection refinements all
    # drie mee.
    ${hopPath('/' + COND_HOP + '/^prov:wasDerivedFrom', '?x', '?g8c')}
    FILTER(?lp IN (rdf:type, rdfs:label, skos:prefLabel, dct:title,
                   dct:description, prov:wasDerivedFrom))
  } UNION {
    # 8d. the label of the CLASS of that coverer — the same relation to 8c as 8b
    # has to 8a: without this hop the chip shows a bare localName.
    ${hopPath('/' + COND_HOP + '/^prov:wasDerivedFrom/rdf:type', '?x', '?g8d')}
    FILTER(?lp IN (rdfs:label, skos:prefLabel))
  }
}
`;
}

export function collectionLevelQuery(iri, { excludeGraphs = DEFAULT_EXCLUDE_GRAPHS } = {}) {
  const P = iriRef(iri);
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
    ${graphFilter(gVar, excludeGraphs)}`
    : body);
  const MEMBER_HOP = '(dct:hasPart|^odrl:partOf)';
  return `${PREFIXES_SPARQL}
CONSTRUCT {
  ?m odrl:partOf ${P} .
  ?m ?lp ?ll .
  ?ty ?tp ?tl .
  ?gc odrl:partOf ?m .
  ?m odrl:partOf ?an .
  ?an ?ap ?al .
  ?an odrl:partOf ?up .
  ?up ?upp ?upl .
}
WHERE {
  {
    # a. the members themselves, with their label and type
    ${P} ${MEMBER_HOP} ?m .
    FILTER(isIRI(?m))
    OPTIONAL {
      ${scoped('?g1', `?m ?lp ?ll .
      FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))`)}
    }
  } UNION {
    # b. the label of the CLASS of each member (this level's group heading)
    ${P} ${MEMBER_HOP}/rdf:type ?ty .
    ${scoped('?g2', `?ty ?tp ?tl .
    FILTER(?tp IN (rdfs:label, skos:prefLabel))`)}
  } UNION {
    # c. is there a level BELOW this member? The membership triple only.
    ${P} ${MEMBER_HOP} ?m .
    ?m ${MEMBER_HOP} ?gc .
    FILTER(isIRI(?m) && isIRI(?gc))
  } UNION {
    # d. the ANCESTORS of the members — this level's ancestry headings.
    #
    # The sub-SELECT is the whole story here. A member of one dataset is also a
    # member of hundreds of others, so a few dozen members can yield tens of
    # thousands of membership triples. Without the sub-SELECT every following
    # pattern carries those bindings; with it — DISTINCT, and the domain-type
    # requirement right INSIDE it — a handful of ancestors remain and the whole
    # level query is an order of magnitude cheaper.
    #
    # That domain-type requirement is not an optimisation but the same one the
    # model makes: only an ancestor with an rdf:type OUTSIDE the ODRL core is a
    # heading members fall under; a bare ODRL collection is another SELECTION of
    # the same members and would
    # honderden zinloze koppen opleveren. Zie groupMembersByAncestry.
    #
    # Both heading levels come from one sub-SELECT (the model's head-level
    # constant is exactly two as well): first the direct ancestor with its label,
    # then through the UNION the ancestor ABOVE it with its own. The membership
    # triples come along, or the model does not know the connection.
    { SELECT DISTINCT ?an WHERE {
        ${P} ${MEMBER_HOP}/odrl:partOf ?an .
        FILTER(isIRI(?an))
        ${DOMAIN_TYPED('?an', 'd')}
      } }
    {
      # the membership triple member -> ancestor: without it the model does not
      # know the connection. As its own branch, AFTER the sub-SELECT, so the join
      # runs over the handful of found ancestors instead of over all
      # membership triples of every member, which measured noticeably cheaper on
      # the largest dataset.
      ${P} ${MEMBER_HOP} ?m .
      ?m odrl:partOf ?an .
      FILTER(isIRI(?m))
    } UNION {
      ${scoped('?g4', `?an ?ap ?al .
      FILTER(?ap IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))`)}
    } UNION {
      ?an odrl:partOf ?up .
      FILTER(isIRI(?up))
      ${DOMAIN_TYPED('?up', 'e')}
      ${scoped('?g5', `?up ?upp ?upl .
      FILTER(?upp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))`)}
    }
  }
}
`;
}

export const NODE_REFS_LIMIT = 400;

export function nodeRefsQuery(iri, {
  limit = NODE_REFS_LIMIT, excludeGraphs = DEFAULT_EXCLUDE_GRAPHS,
} = {}) {
  const P = iriRef(iri);
  const lim = Math.max(1, limit | 0);
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
    ${graphFilter(gVar, excludeGraphs)}`
    : body);
  const LABEL_PREDS = 'FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title, rdf:type))';
  return `${PREFIXES_SPARQL}
CONSTRUCT {
  ${P} ?out ?object .
  ?subject ?in ${P} .
  ?object ?lp ?ll .
  ?subject ?lp ?ll .
}
WHERE {
  {
    # a. what this node says itself (literals and references), with the labels
    #    of the nodes it points at.
    { SELECT ?out ?object WHERE { ${P} ?out ?object } LIMIT ${lim} }
    OPTIONAL { ${scoped('?g1', `?object ?lp ?ll .
      ${LABEL_PREDS}`)} }
  } UNION {
    # b. who points at this node, with their labels.
    { SELECT ?in ?subject WHERE { ?subject ?in ${P} . FILTER(isIRI(?subject)) } LIMIT ${lim} }
    OPTIONAL { ${scoped('?g2', `?subject ?lp ?ll .
      ${LABEL_PREDS}`)} }
  }
}
`;
}

export const SHAPE_FETCH_LIMIT = 200;

const PREFIXES_SHAPES = `PREFIX sh:   <http://www.w3.org/ns/shacl#>
PREFIX dash: <http://datashapes.org/dash#>
PREFIX shui: <http://www.w3.org/ns/shacl-ui/>
`;

const DISPLAY_ANNOTATION = '(sh:name|sh:description|sh:order|sh:group'
  + '|dash:viewer|dash:propertyRole|shui:viewer|shui:propertyRole)';

const SHAPE_CLOSURE = '(sh:property|sh:group)*';

const PAD_LABEL_PREDS = 'rdfs:label, skos:prefLabel, dct:title, '
  + 'skos:definition, dct:description, rdfs:comment';

export function formShapesQuery({
  excludeGraphs = DEFAULT_EXCLUDE_GRAPHS, limit = SHAPE_FETCH_LIMIT,
} = {}) {
  const lim = Math.max(1, limit | 0);
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
    ${graphFilter(gVar, excludeGraphs)}`
    : body);
  const formShapes = `{ SELECT DISTINCT ?shape ?tc WHERE {
      ?shape a sh:NodeShape .
      ?shape sh:targetClass ?tc .
      ?shape sh:property/${DISPLAY_ANNOTATION} ?ann .
      FILTER(isIRI(?tc))
    } LIMIT ${lim} }`;
  return `${PREFIXES_SPARQL}${PREFIXES_SHAPES}
CONSTRUCT {
  ?s ?p ?o .
  ?pad ?lp ?ll .
  ?sub rdfs:subClassOf ?super .
}
WHERE {
  {
    # 1+2. the shape itself, its property shapes and their PropertyGroups
    ${formShapes}
    ?shape ${SHAPE_CLOSURE} ?s .
    ${scoped('?g1', '?s ?p ?o .')}
  } UNION {
    # 2b. the blank path node of an [ sh:inversePath … ]
    ${formShapes}
    ?shape sh:property/sh:path ?s .
    FILTER(isBlank(?s))
    ${scoped('?g2', '?s ?p ?o .')}
  } UNION {
    # 3. label and definition of the path predicates (the propLabel fallback)
    ${formShapes}
    ?shape sh:property/sh:path ?pad .
    FILTER(isIRI(?pad))
    ${scoped('?g3', `?pad ?lp ?ll .
    FILTER(?lp IN (${PAD_LABEL_PREDS}))`)}
  } UNION {
    # 4. the subclass chains that end at a target class
    ${formShapes}
    ?sub rdfs:subClassOf+ ?tc .
    ?sub rdfs:subClassOf ?super .
  }
}
`;
}

export const NODE_FORM_LIMIT = 400;

export function nodeFormQuery(iri, {
  limit = NODE_FORM_LIMIT, excludeGraphs = DEFAULT_EXCLUDE_GRAPHS,
} = {}) {
  const P = iriRef(iri);
  const lim = Math.max(1, limit | 0);
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
    ${graphFilter(gVar, excludeGraphs)}`
    : body);
  return `${PREFIXES_SPARQL}
CONSTRUCT {
  ${P} ?out ?object .
  ?subject ?in ${P} .
  ?object ?op ?ov .
  ?subject ?sp ?sv .
}
WHERE {
  {
    # a. what this node says itself, with each neighbour's literals and type.
    { SELECT ?out ?object WHERE { ${P} ?out ?object } LIMIT ${lim} }
    OPTIONAL { ${scoped('?g1', `?object ?op ?ov .
      FILTER(isLiteral(?ov) || ?op = rdf:type)`)} }
  } UNION {
    # b. who points at this node — the inverse-path rows — with
    #    the same neighbour data.
    { SELECT ?in ?subject WHERE { ?subject ?in ${P} . FILTER(isIRI(?subject)) } LIMIT ${lim} }
    OPTIONAL { ${scoped('?g2', `?subject ?sp ?sv .
      FILTER(isLiteral(?sv) || ?sp = rdf:type)`)} }
  }
}
`;
}

export const COVERED_COUNT_MAX_CLASSES = 200;
export const COVERED_COUNT_MAX_EXCLUDE = 1000;

export function coveredCountQuery(classes, {
  excludeGraphs = DEFAULT_EXCLUDE_GRAPHS, max = COVERED_COUNT_MAX_CLASSES,
  excludeNodes = null, maxExclude = COVERED_COUNT_MAX_EXCLUDE,
} = {}) {
  const classList = [...(classes || [])].slice(0, Math.max(1, max | 0));
  if (!classList.length) return null;
  const out = [...(excludeNodes || [])];
  if (out.length > Math.max(0, maxExclude | 0)) return null;
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
  ${graphFilter(gVar, excludeGraphs)}`
    : body);
  return `${PREFIXES_SPARQL}
SELECT (COUNT(DISTINCT ?node) AS ?n)
WHERE {
  VALUES ?class { ${classList.map(iriRef).join(' ')} }
  ${scoped('?g1', '?node rdf:type ?class .')}${out.length
  ? `
  FILTER(?node NOT IN (${out.map(iriRef).join(', ')}))` : ''}
}
`;
}

export const NODE_LABELS_MAX = 1000;

export function nodeLabelsQuery(iris, {
  excludeGraphs = DEFAULT_EXCLUDE_GRAPHS, max = NODE_LABELS_MAX,
} = {}) {
  const list = [...(iris || [])];
  if (!list.length || list.length > Math.max(1, max | 0)) return null;
  const scoped = (gVar, body) => (excludeGraphs && excludeGraphs.length
    ? `GRAPH ${gVar} { ${body} }
  ${graphFilter(gVar, excludeGraphs)}`
    : body);
  return `${PREFIXES_SPARQL}
CONSTRUCT { ?n ?lp ?lv }
WHERE {
  VALUES ?n { ${list.map(iriRef).join(' ')} }
  ${scoped('?g1', `?n ?lp ?lv .
    FILTER(?lp IN (rdfs:label, skos:prefLabel, dct:title))`)}
}
`;
}

function ttlEscape(s) {
  return String(s)
    .replace(/\\/g, '\\\\').replace(/"/g, '\\"')
    .replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t');
}

export function langTail(binding) {
  const t = binding && binding['xml:lang'];
  return t && LANGUAGE_TAG.test(t) ? '@' + t : '';
}

function bindingValue(b) { return b ? b.value : null; }

const KIND_CLASS = {
  set: ODRL + 'Set',
  offer: ODRL + 'Offer',
  agreement: ODRL + 'Agreement',
  request: ODRL + 'Request',
};

function validityLines(subject, from, to, validBinding) {
  const type = validBinding && validBinding.type;
  const out = [];
  if (from || to) {
    if (from) out.push(`<${subject}> <${SCHEMA}validFrom> "${ttlEscape(from)}" .`);
    if (to) out.push(`<${subject}> <${SCHEMA}validThrough> "${ttlEscape(to)}" .`);
  } else if (type === 'literal') {
    out.push(`<${subject}> <${DCT}valid> "${ttlEscape(validBinding.value)}" .`);
  }
  return out;
}

export function listSkeletonTurtle(bindings) {
  const lines = new Set();
  const safeIri = (b) => (b && b.type === 'uri' && /^[^<>"{}|^`\\\s]+$/.test(b.value)
    ? b.value : null);
  for (const row of bindings || []) {
    const p = safeIri(row.policy);
    if (!p) continue;
    const kindClass = KIND_CLASS[bindingValue(row.kind)] || KIND_CLASS.set;
    lines.add(`<${p}> a <${kindClass}> .`);
    const title = bindingValue(row.title);
    if (title) {
      const lang = langTail(row.title);
      lines.add(`<${p}> <http://purl.org/dc/terms/title> "${ttlEscape(title)}"${lang} .`);
    }
    const iss = bindingValue(row.issued);
    if (iss) lines.add(`<${p}> <${DCT}issued> "${ttlEscape(iss)}" .`);
    for (const l of validityLines(p, bindingValue(row.validFrom),
      bindingValue(row.validTo), row.valid)) lines.add(l);
    const rev = safeIri(row.revisionOf);
    if (rev) lines.add(`<${p}> <http://www.w3.org/ns/prov#wasRevisionOf> <${rev}> .`);
    const off = safeIri(row.offerRef);
    if (off) lines.add(`<${p}> <http://www.w3.org/ns/prov#wasDerivedFrom> <${off}> .`);
    const req = safeIri(row.requestRef);
    if (req) lines.add(`<${p}> <http://www.w3.org/ns/prov#wasDerivedFrom> <${req}> .`);
    const ans = safeIri(row.answeredByRef);
    if (ans) lines.add(`<${ans}> <http://www.w3.org/ns/prov#wasDerivedFrom> <${p}> .`);
    const a = safeIri(row.assignee);
    if (a) {
      lines.add(`<${p}> <${ODRL}assignee> <${a}> .`);
      const al = bindingValue(row.assigneeLabel);
      if (al) {
        const lang = langTail(row.assigneeLabel);
        lines.add(`<${a}> <http://www.w3.org/2000/01/rdf-schema#label> `
          + `"${ttlEscape(al)}"${lang} .`);
      }
    }
    const c = safeIri(row.container);
    if (c) {
      lines.add(`<${c}> a <${SKELETON_CONTAINER_CLASS}> .`);
      lines.add(`<${p}> <${SKELETON_MEMBER_PRED}> <${c}> .`);
      const vc = parseInt(bindingValue(row.versionCount) || '', 10);
      if (Number.isFinite(vc) && vc > 0) {
        lines.add(`<${c}> <${SKELETON_COUNT_PRED}> "${vc}" .`);
      }
      const ct = bindingValue(row.containerTitle);
      if (ct) {
        const lang = langTail(row.containerTitle);
        lines.add(`<${c}> <http://purl.org/dc/terms/title> "${ttlEscape(ct)}"${lang} .`);
      }
    }
  }
  return [...lines].join('\n') + (lines.size ? '\n' : '');
}

export function containerSkeletonTurtle(bindings) {
  const lines = new Set();
  const safeIri = (b) => (b && b.type === 'uri' && /^[^<>"{}|^`\\\s]+$/.test(b.value)
    ? b.value : null);
  const lit = (s, p, b) => {
    const v = bindingValue(b);
    if (!v) return;
    const lang = langTail(b);
    lines.add(`<${s}> <${p}> "${ttlEscape(v)}"${lang} .`);
  };
  for (const row of bindings || []) {
    const c = safeIri(row.container);
    const v = safeIri(row.version);
    if (!c || !v) continue;
    const kindClass = KIND_CLASS[bindingValue(row.kind)];
    if (!kindClass) continue;
    lines.add(`<${c}> a <${SKELETON_CONTAINER_CLASS}> .`);
    lines.add(`<${c}> <${DCT}type> <${kindClass}> .`);
    lines.add(`<${v}> <${SKELETON_MEMBER_PRED}> <${c}> .`);
    lit(c, DCT + 'title', row.containerTitle);
    lit(v, DCT + 'title', row.title);
    for (const l of validityLines(v, bindingValue(row.validFrom),
      bindingValue(row.validTo), row.valid)) lines.add(l);
    lit(v, DCT + 'issued', row.issued);
  }
  return [...lines].join('\n') + (lines.size ? '\n' : '');
}
