export type Term = { termType?: string; value?: string; id?: string };

export interface PredicateHeader {
  iri: string;
  curie: string;
  label: string | null;
  desc: string | null;
}

export interface Reference {
  term: Term;
  iri: string | null;
  curie: string | null;
  label: string | null;
  desc: string | null;
  predicate: PredicateHeader;
}

export interface Value {
  value: string;
  lang: string | null;
  datatype: string | null;
  predicate: PredicateHeader;
}

export interface NodeHeader {
  term: Term;
  iri: string | null;
  curie: string | null;
  label: string | null;
  desc: string | null;
  types: string[];
}

