export interface Member {
  iri: string;
  curie: string;
  label: string;
  desc?: string | null;
  typeIri: string | null;
  typeLabel: string | null;
  cycle?: boolean;
  hasChildren?: boolean;
}

export interface MemberGroup {
  typed: boolean;
  typeIri: string | null;
  label: string;
  items: Member[];
}

export interface AncestryGroup {
  iri: string;
  curie: string;
  label: string;
  typeIri: string | null;
  items: Member[];
  subgroups: { iri: string; curie: string; label: string; typeIri: string | null; items: Member[] }[];
  count: number;
}

export interface MemberLevel {
  total: number;
  members: Member[];
  ancestry: AncestryGroup[];
  groups: MemberGroup[];
}

